"""Highest version in a list satisfying an npm-style range. See task.md."""

from __future__ import annotations

import re
from collections import namedtuple


class RangeError(ValueError):
    """Raised for malformed range expressions and malformed versions."""


Version = namedtuple("Version", ["major", "minor", "patch", "prerelease"])
Primitive = namedtuple("Primitive", ["op", "version"])
Partial = namedtuple("Partial", ["M", "m", "p", "specified_count", "prerelease"])

NUMERAL = r"(?:0|[1-9]\d*)"
NUMERAL_OR_WILD = r"(?:0|[1-9]\d*|[xX*])"
IDENT = r"[0-9A-Za-z-]+"
IDENT_CHAIN = IDENT + r"(?:\." + IDENT + r")*"

FULL_VERSION_RE = re.compile(
    r"^(?P<major>" + NUMERAL + r")\.(?P<minor>" + NUMERAL + r")\.(?P<patch>" + NUMERAL + r")"
    r"(?:-(?P<prerelease>" + IDENT_CHAIN + r"))?"
    r"(?:\+(?P<build>" + IDENT_CHAIN + r"))?$"
)

PARTIAL_RE = re.compile(
    r"^(?P<major>" + NUMERAL_OR_WILD + r")"
    r"(?:\.(?P<minor>" + NUMERAL_OR_WILD + r")"
    r"(?:\.(?P<patch>" + NUMERAL_OR_WILD + r")"
    r"(?:-(?P<prerelease>" + IDENT_CHAIN + r"))?"
    r"(?:\+(?P<build>" + IDENT_CHAIN + r"))?"
    r")?)?$"
)

IDENT_RE = re.compile(r"^[0-9A-Za-z-]+$")
WILDCARDS = ("x", "X", "*")


def _split_and_validate(s, allow_leading_zero):
    parts = s.split(".")
    for p in parts:
        if p == "" or not IDENT_RE.match(p):
            raise RangeError(f"invalid identifier {p!r}")
        if not allow_leading_zero and p.isdigit() and len(p) > 1 and p[0] == "0":
            raise RangeError(f"invalid identifier {p!r}")
    return tuple(parts)


def parse_version(s):
    """Strictly parse a fully specified version (used for entries of `versions`)."""
    m = FULL_VERSION_RE.match(s)
    if not m:
        raise RangeError(f"malformed version {s!r}")
    prerelease = ()
    if m["prerelease"] is not None:
        prerelease = _split_and_validate(m["prerelease"], allow_leading_zero=False)
    if m["build"] is not None:
        _split_and_validate(m["build"], allow_leading_zero=True)
    return Version(int(m["major"]), int(m["minor"]), int(m["patch"]), prerelease)


def parse_partial(s):
    """Parse a (possibly partial, possibly wildcarded) version used in a range."""
    m = PARTIAL_RE.match(s)
    if not m:
        raise RangeError(f"malformed version {s!r}")

    major_s, minor_s, patch_s = m["major"], m["minor"], m["patch"]
    tokens = [t for t in (major_s, minor_s, patch_s) if t is not None]

    wildcard_seen = False
    specified_count = 0
    for tok in tokens:
        is_wild = tok in WILDCARDS
        if wildcard_seen and not is_wild:
            raise RangeError(f"malformed version {s!r}: component after wildcard")
        if is_wild:
            wildcard_seen = True
        else:
            specified_count += 1

    fully_specified = len(tokens) == 3 and specified_count == 3

    if (m["prerelease"] is not None or m["build"] is not None) and not fully_specified:
        raise RangeError(f"malformed version {s!r}: suffix requires full version")

    prerelease = None
    if m["prerelease"] is not None:
        prerelease = _split_and_validate(m["prerelease"], allow_leading_zero=False)
    if m["build"] is not None:
        _split_and_validate(m["build"], allow_leading_zero=True)

    def as_int(tok):
        if tok is None or tok in WILDCARDS:
            return 0
        return int(tok)

    return Partial(as_int(major_s), as_int(minor_s), as_int(patch_s), specified_count, prerelease)


def _increment_last_specified(partial):
    sc = partial.specified_count
    if sc == 1:
        return Version(partial.M + 1, 0, 0, ())
    return Version(partial.M, partial.m + 1, 0, ())


def _desugar_bare(partial):
    sc = partial.specified_count
    if sc == 3:
        return [Primitive("=", Version(partial.M, partial.m, partial.p, partial.prerelease or ()))]
    if sc == 0:
        return [Primitive(">=", Version(0, 0, 0, ()))]
    lower = Version(partial.M, partial.m if sc >= 2 else 0, 0, ())
    upper = _increment_last_specified(partial)
    return [Primitive(">=", lower), Primitive("<", upper)]


def _desugar_caret(partial):
    sc = partial.specified_count
    comps = [partial.M, partial.m, partial.p]
    lower = Version(partial.M, partial.m, partial.p, partial.prerelease or ())

    idx = None
    for i in range(sc):
        if comps[i] != 0:
            idx = i
            break
    if idx is None:
        idx = sc - 1

    new_comps = comps[:]
    new_comps[idx] += 1
    for j in range(idx + 1, 3):
        new_comps[j] = 0
    upper = Version(new_comps[0], new_comps[1], new_comps[2], ())
    return [Primitive(">=", lower), Primitive("<", upper)]


def _desugar_tilde(partial):
    sc = partial.specified_count
    lower = Version(partial.M, partial.m, partial.p, partial.prerelease or ())
    if sc >= 2:
        upper = Version(partial.M, partial.m + 1, 0, ())
    else:
        upper = Version(partial.M + 1, 0, 0, ())
    return [Primitive(">=", lower), Primitive("<", upper)]


def _parse_comparator_token(token):
    for op in (">=", "<=", ">", "<"):
        if token.startswith(op):
            rest = token[len(op):]
            partial = parse_partial(rest)
            if partial.specified_count != 3:
                raise RangeError(f"{op!r} requires a fully specified version, got {token!r}")
            v = Version(partial.M, partial.m, partial.p, partial.prerelease or ())
            return [Primitive(op, v)]

    if token.startswith("^"):
        rest = token[1:]
        partial = parse_partial(rest)
        if partial.specified_count == 0:
            raise RangeError(f"'^' needs at least a major component, got {token!r}")
        return _desugar_caret(partial)

    if token.startswith("~"):
        rest = token[1:]
        partial = parse_partial(rest)
        if partial.specified_count == 0:
            raise RangeError(f"'~' needs at least a major component, got {token!r}")
        return _desugar_tilde(partial)

    if token.startswith("="):
        rest = token[1:]
        partial = parse_partial(rest)
        return _desugar_bare(partial)

    partial = parse_partial(token)
    return _desugar_bare(partial)


def _parse_hyphen(tok_a, tok_b):
    a = parse_partial(tok_a)
    b = parse_partial(tok_b)
    if a.specified_count == 0:
        raise RangeError(f"hyphen range lower bound needs a major component, got {tok_a!r}")
    if b.specified_count == 0:
        raise RangeError(f"hyphen range upper bound needs a major component, got {tok_b!r}")

    lower = Version(a.M, a.m, a.p, a.prerelease or ())
    if b.specified_count == 3:
        upper = Version(b.M, b.m, b.p, b.prerelease or ())
        return [Primitive(">=", lower), Primitive("<=", upper)]

    upper = _increment_last_specified(b)
    return [Primitive(">=", lower), Primitive("<", upper)]


def _parse_comparator_set(s):
    tokens = re.split(r"\s+", s.strip())
    tokens = [t for t in tokens if t]

    if len(tokens) == 3 and tokens[1] == "-":
        return _parse_hyphen(tokens[0], tokens[2])

    if any(t == "-" for t in tokens):
        raise RangeError(f"malformed hyphen range in {s!r}")

    primitives = []
    for t in tokens:
        primitives.extend(_parse_comparator_token(t))
    return primitives


def parse_range(range_expr):
    trimmed = range_expr.strip()
    if trimmed == "":
        return [[Primitive(">=", Version(0, 0, 0, ()))]]

    comparator_sets = []
    for part in trimmed.split("||"):
        p = part.strip()
        if p == "":
            raise RangeError(f"empty comparator set in {range_expr!r}")
        comparator_sets.append(_parse_comparator_set(p))
    return comparator_sets


def _compare_prerelease(pre1, pre2):
    for a, b in zip(pre1, pre2):
        if a == b:
            continue
        a_num, b_num = a.isdigit(), b.isdigit()
        if a_num and b_num:
            ai, bi = int(a), int(b)
            if ai != bi:
                return -1 if ai < bi else 1
            continue
        if a_num and not b_num:
            return -1
        if not a_num and b_num:
            return 1
        return -1 if a < b else 1
    if len(pre1) < len(pre2):
        return -1
    if len(pre1) > len(pre2):
        return 1
    return 0


def compare_precedence(v1, v2):
    if v1.major != v2.major:
        return -1 if v1.major < v2.major else 1
    if v1.minor != v2.minor:
        return -1 if v1.minor < v2.minor else 1
    if v1.patch != v2.patch:
        return -1 if v1.patch < v2.patch else 1
    if not v1.prerelease and not v2.prerelease:
        return 0
    if not v1.prerelease:
        return 1
    if not v2.prerelease:
        return -1
    return _compare_prerelease(v1.prerelease, v2.prerelease)


def _satisfies_primitive(candidate, primitive):
    c = compare_precedence(candidate, primitive.version)
    op = primitive.op
    if op == "=":
        return c == 0
    if op == ">":
        return c > 0
    if op == ">=":
        return c >= 0
    if op == "<":
        return c < 0
    return c <= 0  # "<="


def _satisfies_set(candidate, primitives):
    if not all(_satisfies_primitive(candidate, p) for p in primitives):
        return False
    if candidate.prerelease:
        return any(
            p.version.prerelease
            and p.version.major == candidate.major
            and p.version.minor == candidate.minor
            and p.version.patch == candidate.patch
            for p in primitives
        )
    return True


def _satisfies_range(candidate, comparator_sets):
    return any(_satisfies_set(candidate, s) for s in comparator_sets)


def max_satisfying(versions: list[str], range_expr: str) -> str | None:
    """Return the highest version in `versions` that satisfies `range_expr`."""
    comparator_sets = parse_range(range_expr)

    best = None
    best_parsed = None
    for s in versions:
        parsed = parse_version(s)
        if _satisfies_range(parsed, comparator_sets):
            if best is None or compare_precedence(parsed, best_parsed) > 0:
                best = s
                best_parsed = parsed
    return best
